insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g2_health_v1'
from (values
('115.14.b.1',2,'Which organ is part of the respiratory system and helps you breathe?','["lungs", "heart", "brain", "stomach"]'::jsonb,0,'The lungs move air in and out.','original'),
('115.14.b.1',3,'The brain and nerves make up which body system?','["digestive system", "nervous system", "skeletal system", "muscular system"]'::jsonb,1,'The nervous system sends messages.','original'),
('115.14.b.1',3,'Which two body systems work together when you run?','["hair and nails", "digestive and nervous only", "muscular and skeletal", "none of them"]'::jsonb,2,'Muscles move bones.','original'),
('115.14.b.1',3,'When you exercise, your heart beats faster to deliver more...','["noise", "candy", "light", "blood and oxygen"]'::jsonb,3,'The circulatory system carries oxygen.','original'),
('115.14.b.2.A',2,'A regular checkup with a doctor helps you...','["stay healthy and catch problems early", "skip school forever", "avoid brushing", "become sick"]'::jsonb,0,'Checkups prevent illness.','original'),
('115.14.b.2.A',3,'Seeing a dentist twice a year helps prevent...','["hiccups", "cavities", "sunburn", "homework"]'::jsonb,1,'Dental visits protect teeth.','original'),
('115.14.b.2.B',2,'If your throat hurts and you feel hot, you should tell...','["nobody", "a stranger", "an adult", "a toy"]'::jsonb,2,'Adults can help you feel better.','original'),
('115.14.b.2.B',3,'When you do not feel well, a good action is to...','["ignore it", "eat only candy", "run a race", "rest and drink water"]'::jsonb,3,'Rest helps recovery.','original'),
('115.14.b.2.C',2,'Good hygiene includes...','["washing hands and brushing teeth", "sharing towels", "skipping baths", "never washing"]'::jsonb,0,'Hygiene prevents illness.','original'),
('115.14.b.2.C',3,'Why should you not share your toothbrush?','["it is too big", "germs can spread", "it wears out", "it is too pretty"]'::jsonb,1,'Sharing spreads germs.','original'),
('115.14.b.2.D',3,'Germs can spread through the air when someone...','["draws", "reads silently", "sneezes", "sleeps"]'::jsonb,2,'Droplets carry germs.','original'),
('115.14.b.2.D',3,'Which action helps prevent spreading germs at school?','["licking pencils", "sharing water bottles", "coughing on the desk", "washing hands before lunch"]'::jsonb,3,'Handwashing removes germs.','original'),
('115.14.b.2.E',3,'Asthma is an illness that makes it hard to...','["breathe", "hear", "taste", "see"]'::jsonb,0,'Asthma affects airways.','original'),
('115.14.b.2.E',4,'A person with diabetes must watch their...','["height", "blood sugar", "eye color", "shoe size"]'::jsonb,1,'Diabetes affects blood sugar.','original'),
('115.14.b.2.E',4,'Epilepsy is a condition that can cause...','["a cold", "a broken bone", "seizures", "sunburn"]'::jsonb,2,'Epilepsy involves the brain.','original'),
('115.14.b.2.F',3,'After a tick bite, you should tell an adult if you have...','["a smile", "a new backpack", "a loose tooth", "a fever or a rash"]'::jsonb,3,'Illness signs after bites need care.','original'),
('115.14.b.2.F',4,'A mosquito bite can sometimes cause illness with symptoms like...','["fever and body aches", "a good grade", "a new haircut", "a loud laugh"]'::jsonb,0,'Insect-borne illness causes fever.','original'),
('115.14.b.3.A',2,'A healthy way to say what you need is to...','["slam doors", "use words calmly", "cry without telling", "scream"]'::jsonb,1,'Words communicate needs.','original'),
('115.14.b.3.A',3,'Which sentence shares a feeling in a healthy way?','["\"Go away.\"", "\"I''m never talking again.\"", "\"I feel sad because I lost my toy.\"", "\"You are dumb.\""]'::jsonb,2,'I-statements are healthy.','original'),
('115.14.b.3.B',2,'Counting backward from five can help you...','["forget your name", "get louder", "run faster", "calm down"]'::jsonb,3,'Counting calms the body.','original'),
('115.14.b.3.B',3,'A self-management strategy is to...','["take a break and breathe", "ignore everyone", "break something", "yell at a friend"]'::jsonb,0,'Breaks help you reset.','original'),
('115.14.b.3.C',3,'Your thoughts can change your...','["height", "emotions", "shoe size", "eye color"]'::jsonb,1,'Thoughts and emotions are linked.','original'),
('115.14.b.3.C',3,'If you think "I can''t do this," you might feel...','["calm", "excited", "discouraged", "proud"]'::jsonb,2,'Negative thoughts cause negative feelings.','original'),
('115.14.b.3.D',3,'Peer influence means a person your age can...','["make you taller", "give you wings", "grow your hair", "change how you think or act"]'::jsonb,3,'Peers can affect choices.','original'),
('115.14.b.3.D',4,'A positive peer influence would be a friend who...','["encourages you to follow rules", "dares you to break rules", "ignores you", "teases you"]'::jsonb,0,'Positive influence supports good choices.','original'),
